import { useEffect, useState, useRef } from 'react';
import './audio-unlock.scss';

// Simple utility to check if we're on localhost
const isLocalhost = (): boolean => {
  return window.location.hostname === 'localhost' || 
         window.location.hostname === '127.0.0.1' ||
         window.location.hostname.includes('192.168.');
};

type AudioUnlockProps = {
  onUnlock: () => void;
};

const AudioUnlock: React.FC<AudioUnlockProps> = ({ onUnlock }) => {
  const [showUnlock, setShowUnlock] = useState<boolean>(!isLocalhost());
  const [audioState, setAudioState] = useState<string>('waiting');
  const timeoutRef = useRef<number | null>(null);

  // Handle the unlock button click
  const handleUnlock = () => {
    console.log('User interaction detected - unlocking audio');
    
    // Direct unlock without any silent audio playing logic
    console.log('Directly calling onUnlock without audio.play()');
    setAudioState('unlocked');
    setShowUnlock(false);
    onUnlock();
  };

  // Auto-hide for localhost environments
  useEffect(() => {
    if (isLocalhost()) {
      console.log('Running on localhost - no audio unlock required');
      setShowUnlock(false);
      // Still notify parent that we've "unlocked"
      onUnlock();
    }
    
    // Cleanup timeout on unmount
    return () => {
      if (timeoutRef.current) {
        window.clearTimeout(timeoutRef.current);
        timeoutRef.current = null;
      }
    };
  }, [onUnlock]);

  if (!showUnlock) {
    return null;
  }

  return (
    <div className="audio-unlock-overlay">
      <div className="audio-unlock-container">
        <h2>Enable Audio</h2>
        <p>
          {audioState === 'waiting' && 'Tap or click the button below to enable audio playback.'}
          {audioState === 'unlocking' && 'Enabling audio...'}
          {audioState === 'error' && 'There was an issue enabling audio. The app will still work, but you may not hear responses.'}
        </p>
        <div className="button-container">
          <button 
            className="unlock-button"
            onClick={handleUnlock}
            disabled={audioState !== 'waiting' && audioState !== 'error'}
          >
            {audioState === 'waiting' && 'Enable Audio'}
            {audioState === 'unlocking' && 'Enabling...'}
            {audioState === 'error' && 'Try Again'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default AudioUnlock; 