import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  MultimodalLiveAPIClientConnection,
  MultimodalLiveClient,
} from "../lib/multimodal-live-client";
import { LiveConfig } from "../multimodal-live-types";
import { AudioStreamer } from "../lib/audio-streamer";
import { audioContext } from "../lib/utils";
import VolMeterWorket from "../lib/worklets/vol-meter";

export type UseLiveAPIResults = {
  client: MultimodalLiveClient;
  setConfig: (config: LiveConfig) => void;
  config: LiveConfig;
  connected: boolean;
  connect: () => Promise<void>;
  disconnect: () => Promise<void>;
  volume: number;
};

// Extended connection type with audioUnlocked flag
export type UseLiveAPIProps = MultimodalLiveAPIClientConnection & {
  audioUnlocked?: boolean;
};

export function useLiveAPI({
  url,
  apiKey,
  audioUnlocked = false,
}: UseLiveAPIProps): UseLiveAPIResults {
  const client = useMemo(
    () => new MultimodalLiveClient({ url, apiKey }),
    [url, apiKey],
  );
  const audioStreamerRef = useRef<AudioStreamer | null>(null);
  const audioInitializedRef = useRef<boolean>(false);

  const [connected, setConnected] = useState(false);
  const [config, setConfig] = useState<LiveConfig>({
    model: "models/gemini-2.0-flash-exp",
  });
  const [volume, setVolume] = useState(0);

  // register audio for streaming server -> speakers
  useEffect(() => {
    // Only initialize audio if we're on localhost or the user has explicitly unlocked audio
    const shouldInitializeAudio = audioUnlocked || 
      window.location.hostname === 'localhost' || 
      window.location.hostname === '127.0.0.1' ||
      window.location.hostname.includes('192.168.');
    
    if (!shouldInitializeAudio) {
      console.log("Audio initialization deferred until user interaction");
      return;
    }
    
    // Don't re-initialize if already done
    if (audioInitializedRef.current && audioStreamerRef.current) {
      console.log("Audio already initialized, skipping initialization");
      return;
    }
    
    const initAudioStreamer = async () => {
      try {
        console.log("Initializing audio output context...");
        const audioCtx = await audioContext({ id: "audio-out" });
        
        console.log("Creating AudioStreamer...");
        audioStreamerRef.current = new AudioStreamer(audioCtx);
        
        // Ensure context is resumed
        if (audioCtx.state !== "running") {
          console.log("Resuming audio output context from state:", audioCtx.state);
          await audioCtx.resume();
          console.log("Audio output context now in state:", audioCtx.state);
        }
        
        console.log("Adding volume meter worklet to output stream...");
        await audioStreamerRef.current.addWorklet<any>(
          "vumeter-out", 
          VolMeterWorket, 
          (ev: any) => {
            setVolume(ev.data.volume);
          }
        );
        
        console.log("Audio output system initialized successfully");
        audioInitializedRef.current = true;
      } catch (error) {
        console.error("Failed to initialize audio output system:", error);
      }
    };
    
    initAudioStreamer();
    
    // Also listen for manual audio unlock events
    const handleAudioUnlock = () => {
      console.log("Audio unlock event received");
      if (!audioInitializedRef.current) {
        initAudioStreamer();
      }
    };
    
    window.addEventListener('audio-unlocked', handleAudioUnlock);
    return () => {
      window.removeEventListener('audio-unlocked', handleAudioUnlock);
    };
  }, [audioUnlocked]);

  useEffect(() => {
    const onClose = () => {
      setConnected(false);
    };

    const stopAudioStreamer = () => {
      console.log("Stopping audio streamer due to interruption");
      audioStreamerRef.current?.stop();
    };

    const onAudio = (data: ArrayBuffer) => {
      // If audio isn't initialized and we're not on localhost, we need to check
      // if audioUnlocked is true before trying to play audio
      if (!audioStreamerRef.current) {
        // Skip audio playback if audio not unlocked on non-localhost domains
        if (!audioUnlocked && !window.location.hostname.includes('localhost')) {
          console.warn("Received audio data but audio not unlocked yet - skipping playback");
          return;
        }
        
        console.warn("Received audio data but AudioStreamer not initialized");
        return;
      }
      
      // Ensure audio is resumed before playing
      if (audioStreamerRef.current.context.state !== "running") {
        console.log("Resuming audio context before playback");
        audioStreamerRef.current.resume();
      }
      
      audioStreamerRef.current.addPCM16(new Uint8Array(data));
    };

    client
      .on("close", onClose)
      .on("interrupted", stopAudioStreamer)
      .on("audio", onAudio);

    return () => {
      client
        .off("close", onClose)
        .off("interrupted", stopAudioStreamer)
        .off("audio", onAudio);
    };
  }, [client, audioUnlocked]);

  const connect = useCallback(async () => {
    console.log("Connecting with config:", config);
    if (!config) {
      throw new Error("config has not been set");
    }
    
    // Check audio context state
    console.log("Audio context state before connection:", 
      audioStreamerRef.current ? audioStreamerRef.current.context.state : "no context");
    
    // Make sure audio streamer is ready (if audio is unlocked)
    if (audioStreamerRef.current) {
      console.log("Resuming audio streamer for new connection");
      try {
        await audioStreamerRef.current.resume();
        console.log("Audio streamer resumed, new state:", audioStreamerRef.current.context.state);
      } catch (audioError) {
        console.warn("Error resuming audio streamer:", audioError);
      }
    } else {
      console.warn("AudioStreamer not initialized before connection");
      
      // Try to initialize now as a last resort
      try {
        console.log("Attempting last-minute audio initialization");
        const audioCtx = await audioContext({ id: "audio-out" });
        audioStreamerRef.current = new AudioStreamer(audioCtx);
        await audioCtx.resume();
        console.log("Last-minute audio initialization successful, state:", audioCtx.state);
      } catch (initError) {
        console.error("Last-minute audio initialization failed:", initError);
      }
    }
    
    console.log("Disconnecting any existing connections before connecting...");
    client.disconnect();
    
    try {
      console.log("Attempting to connect to WebSocket...");
      await client.connect(config);
      console.log("WebSocket connection successful!");
      setConnected(true);
    } catch (connectionError) {
      console.error("WebSocket connection failed:", connectionError);
      throw connectionError;
    }
  }, [client, setConnected, config]);

  const disconnect = useCallback(async () => {
    client.disconnect();
    setConnected(false);
  }, [setConnected, client]);

  return {
    client,
    config,
    setConfig,
    connected,
    connect,
    disconnect,
    volume,
  };
}
