import { useRef, useState, useEffect } from "react";
import "./App.scss";
import { LiveAPIProvider } from "./contexts/LiveAPIContext";
import SidePanel from "./components/side-panel/SidePanel";
import { Altair } from "./components/altair/Altair";
import ControlTray from "./components/control-tray/ControlTray";
import AudioUnlock from "./components/AudioUnlock";
import cn from "classnames";

const API_KEY = process.env.REACT_APP_GEMINI_API_KEY as string;
if (typeof API_KEY !== "string") {
  throw new Error("set REACT_APP_GEMINI_API_KEY in .env");
}

const host = "generativelanguage.googleapis.com";
const uri = `wss://${host}/ws/google.ai.generativelanguage.v1alpha.GenerativeService.BidiGenerateContent`;

function App() {
  // this video reference is used for displaying the active stream, whether that is the webcam or screen capture
  // feel free to style as you see fit
  const videoRef = useRef<HTMLVideoElement>(null);
  // either the screen capture, the video or null, if null we hide it
  const [videoStream, setVideoStream] = useState<MediaStream | null>(null);
  // Track if audio has been unlocked by user interaction
  const [audioUnlocked, setAudioUnlocked] = useState<boolean>(false);

  // Test effect to verify changes are reflected in local development
  useEffect(() => {
    console.log('%c TEST - VERIFY LOCAL DEV IS WORKING', 'background: #222; color: #bada55; font-size: 16px;');
    console.log('Environment is:', window.location.hostname);
    console.log('Is localhost?', window.location.hostname === 'localhost');
    console.log('API key available?', API_KEY ? 'Yes (length: ' + API_KEY.length + ')' : 'No');
    console.log('API key first 4 chars:', API_KEY ? API_KEY.substring(0, 4) + '...' : 'N/A');
  }, []);

  // Handle audio unlock
  const handleAudioUnlock = () => {
    setAudioUnlocked(true);
    console.log("Audio unlocked by user interaction");
    
    // We could also dispatch a custom event that our audio handling code listens for
    const audioUnlockEvent = new CustomEvent('audio-unlocked');
    window.dispatchEvent(audioUnlockEvent);
  };

  return (
    <div className="App">
      {/* Audio unlock overlay */}
      <AudioUnlock onUnlock={handleAudioUnlock} />
      
      <LiveAPIProvider url={uri} apiKey={API_KEY} audioUnlocked={audioUnlocked}>
        <div className="streaming-console">
          <SidePanel />
          <main>
            <div className="main-app-area">
              {/* APP goes here */}
              <Altair />
              <video
                className={cn("stream", {
                  hidden: !videoRef.current || !videoStream,
                })}
                ref={videoRef}
                autoPlay
                playsInline
              />
            </div>

            <ControlTray
              videoRef={videoRef}
              supportsVideo={true}
              onVideoStreamChange={setVideoStream}
            >
              {/* put your own buttons here */}
            </ControlTray>
          </main>
        </div>
      </LiveAPIProvider>
    </div>
  );
}

export default App;
